pub fn fn_outram_park_fork_dwsim_libs__clean_energies__pem_fuel_cell__inerts_outlet_specific_enthalpy(hydrogen_inlet_specific_enthalpy_j_per_kg: f64, oxygen_inlet_specific_enthalpy_j_per_kg: f64, hydrogen_inlet_mass_flow_kg_per_s: f64, oxygen_inlet_mass_flow_kg_per_s: f64, thermal_power: f64) -> f64 { ::outram_park_fork_dwsim_libs::clean_energies::pem_fuel_cell::inerts_outlet_specific_enthalpy(hydrogen_inlet_specific_enthalpy_j_per_kg, oxygen_inlet_specific_enthalpy_j_per_kg, hydrogen_inlet_mass_flow_kg_per_s, oxygen_inlet_mass_flow_kg_per_s, from_si(thermal_power)) }

