pub fn fn_outram_park_fork_dwsim_libs__clean_energies__pem_fuel_cell__sweep_polarization_curve(model: Py_outram_park_fork_dwsim_libs__clean_energies__PemFuelCellModel, start_a: f64, stop_a: f64, step_a: f64) -> PyResult<Py_outram_park_fork_dwsim_libs__clean_energies__pem_fuel_cell__PolarizationCurve> { err(::outram_park_fork_dwsim_libs::clean_energies::pem_fuel_cell::sweep_polarization_curve(&model.inner, start_a, stop_a, step_a)).map(|v| Py_outram_park_fork_dwsim_libs__clean_energies__pem_fuel_cell__PolarizationCurve { inner: v }) }

