pub fn fn_outram_park_fork_dwsim_libs__clean_energies__wind_turbine__disk_area_from_rotor_diameter(rotor_diameter: f64) -> f64 { to_si(::outram_park_fork_dwsim_libs::clean_energies::wind_turbine::disk_area_from_rotor_diameter(from_si(rotor_diameter))) }

