pub fn fn_outram_park_fork_dwsim_libs__thermo__lkp__enthalpy_departure(tr: f64, pr: f64, w: f64, tc: f64, phase: Py_outram_park_fork_dwsim_libs__thermo__lkp__Phase) -> Option<f64> { ::outram_park_fork_dwsim_libs::thermo::lkp::enthalpy_departure(tr, pr, w, tc, phase.inner).map(|e| e) }

    // @item fn:outram_park_fork_dwsim_libs::thermo::lkp::enthalpy_departure_dimensionless
#[doc = "Dimensionless enthalpy departure `(H − H_ig) / (R Tc)` [-] of one reference\nfluid at reduced `tr, pr` [-] (`LeeKeslerPlocker.vb` L361 / L384).\n\n`= Tr [ Z − 1 − (b2 + 2b3/Tr + 3b4/Tr²)/(Tr Vr) − (c2 − 3c3/Tr²)/(2 Tr Vr²)`\n`      + d2/(5 Tr Vr⁵) + 3E ]`, with `E = c4/(2 Tr³ γ)[β + 1 − (β + 1 +`\n`γ/Vr²) exp(−γ/Vr²)]`. `Vr` is the fluid's own reduced volume. Returns `None`\nif the reduced-volume solve fails."]
#[pyfunction(name = "enthalpy_departure_dimensionless")]
pub fn fn_outram_park_fork_dwsim_libs__thermo__lkp__enthalpy_departure_dimensionless(fluid: Py_outram_park_fork_dwsim_libs__thermo__lkp__LkFluid, tr: f64, pr: f64, phase: Py_outram_park_fork_dwsim_libs__thermo__lkp__Phase) -> Option<f64> { ::outram_park_fork_dwsim_libs::thermo::lkp::enthalpy_departure_dimensionless(fluid.inner, tr, pr, phase.inner).map(|e| e) }

    // @item fn:outram_park_fork_dwsim_libs::thermo::lkp::entropy_departure
#[doc = "Pure-fluid entropy departure `S − S_ig` [J/(mol·K)] at reduced `tr, pr` [-]\nand acentric factor `w` [-].\n\n`S − S_ig = R [ s⁰ + (ω/0.3978)(sʳᵉᶠ − s⁰) ]` (`LeeKeslerPlocker.vb`\nL273/L510). Returns `None` if a reduced-volume solve fails."]
#[pyfunction(name = "entropy_departure")]
pub fn fn_outram_park_fork_dwsim_libs__thermo__lkp__entropy_departure(tr: f64, pr: f64, w: f64, phase: Py_outram_park_fork_dwsim_libs__thermo__lkp__Phase) -> Option<f64> { ::outram_park_fork_dwsim_libs::thermo::lkp::entropy_departure(tr, pr, w, phase.inner).map(|e| e) }

    // @item fn:outram_park_fork_dwsim_libs::thermo::lkp::entropy_departure_dimensionless
#[doc = "Dimensionless entropy departure `(S − S_ig) / R` [-] of one reference fluid\nat reduced `tr, pr` [-] (`LeeKeslerPlocker.vb` L483 / L508).\n\n`= ln Z − (b1 + b3/Tr² + 2b4/Tr³)/Vr − (c1 − 2c3/Tr³)/(2 Vr²)`\n`  − d1/(5 Vr⁵) + 2E`, with the same `E` as\n[`enthalpy_departure_dimensionless`]. This is the residual entropy at the\nsystem `(T, P)` relative to the ideal gas at the *same* `(T, P)`\n(`ln Z` term; DWSIM's active branch uses `Math.Log(1)` reference,\n`LeeKeslerPlocker.vb` L483). Returns `None` if the solve fails."]
