#[pyfunction(name = "prsv2_a_i")]
pub fn fn_outram_park_fork_dwsim_libs__thermo__prsv2_full__prsv2_a_i(comp: Py_outram_park_fork_dwsim_libs__thermo__Component, kappa1: f64, kappa2: f64, kappa3: f64, t: f64) -> f64 { ::outram_park_fork_dwsim_libs::thermo::prsv2_full::prsv2_a_i(&comp.inner, kappa1, kappa2, kappa3, t) }

